"""Decoder for the internal ``trk`` telemetry record format.

Frames have a one-byte type, a little-endian uint16 payload length, a
payload, and a little-endian CRC32. The CRC covers the header and payload
and uses the feed's seed, 0x9C2F41B7. Payload integers are big-endian.
"""

from datetime import datetime, timedelta, timezone
import zlib


_CRC_SEED = 0x9C2F41B7
_EPOCH = datetime(2000, 1, 2, tzinfo=timezone.utc)
_FLAG_NAMES = ("low_battery", "recal", "stale")


def decode_records(data: bytes) -> list[dict]:
    """Decode complete frames, rejecting truncated or corrupt input.

    Samples (type 2) contain minutes since the epoch, an unsigned 24-bit
    value in thousandths, and flags. Batches (type 7) contain a uint16
    count, uint16 values in hundredths, and flags.
    """
    records = []
    offset = 0
    while offset < len(data):
        if len(data) - offset < 3:
            raise ValueError("truncated record header")
        kind = data[offset]
        length = int.from_bytes(data[offset + 1:offset + 3], "little")
        payload_end = offset + 3 + length
        frame_end = payload_end + 4
        if frame_end > len(data):
            raise ValueError("truncated record payload or checksum")
        checksum = int.from_bytes(data[payload_end:frame_end], "little")
        if zlib.crc32(data[offset:payload_end], _CRC_SEED) != checksum:
            raise ValueError("record checksum mismatch")

        payload = data[offset + 3:payload_end]
        if kind == 2:
            if length != 8:
                raise ValueError("invalid sample payload length")
            minutes = int.from_bytes(payload[:4], "big")
            timestamp = _EPOCH + timedelta(minutes=minutes)
            record = {
                "type": "sample",
                "ts": timestamp.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "value": int.from_bytes(payload[4:7], "big") / 1000,
            }
        elif kind == 7:
            if length < 3:
                raise ValueError("invalid batch payload length")
            count = int.from_bytes(payload[:2], "big")
            if length != 3 + 2 * count:
                raise ValueError("invalid batch payload length")
            record = {
                "type": "batch",
                "values": [
                    int.from_bytes(payload[i:i + 2], "big") / 100
                    for i in range(2, 2 + 2 * count, 2)
                ],
            }
        else:
            raise ValueError(f"unknown record type: {kind}")
        record["flags"] = [
            name for bit, name in enumerate(_FLAG_NAMES)
            if payload[-1] & (1 << bit)
        ]
        records.append(record)
        offset = frame_end
    return records
PY
